const rawText = $input.first().json.content.parts[0].text;

const parsed = JSON.parse(rawText);

return {
  ...parsed,
  status: "in progress"
};

const list = $("Format and sort base64 to n8n binary").all()
  // matches earlier filename when it is saved
  .map(item => `file '/home/node/.n8n-files/part_${item.json.sequence}.mp4'`)
  .join('\n')

const Buffer = globalThis.Buffer;

return [
  {
    json: {
      list
    },
    binary: {
      data: {
        data: Buffer.from(list).toString('base64'),
        mimeType: 'text/plain',
        fileName: 'list.txt'
      }
    }
  }
]

return $('Edit Fields')
  .all()
  .sort((a, b) => a.json.sequence - b.json.sequence)
  .map(item => {
    return {
      json: item.json,
      binary: {
        video: {
          data: item.json.data,
          mimeType: 'video/mp4',
          fileName: `part_${item.json.sequence}.mp4`
        }
      }
    }
})

